package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"sort"
	"strings"
)

type LocationServiceData struct {
	ServiceDefinitions []ServiceDefinition `json:"serviceDefinitions"`
}

type ServiceDefinition struct {
	Identifier        string            `json:"identifier"`
	ParentServiceType string            `json:"parentServiceType"`
	ParentIdentifier  string            `json:"parentIdentifier"`
	LocationMappings  []LocationMapping `json:"locationMappings"`
}

type LocationMapping struct {
	AccessMappingMoniker string `json:"accessMappingMoniker"`
	Location             string `json:"location"`
}

type ConnectionData struct {
	LocationServiceData LocationServiceData `json:"locationServiceData"`
}

const PipelineScaleUnitType = "0000005a-0000-8888-8000-000000000000"
const ArtifactCacheScaleUnitType = "0000006d-0000-8888-8000-000000000000"
const RunnerScaleUnitType = "0000006f-0000-8888-8000-000000000000"

const fileContent = `// Code generated by script/generate_scale_unit_map.go DO NOT EDIT.
package azpclient

// This file is generated by script/generate_scale_unit_map.go
// Run "go generate" in this directory to regenerate this file

var scaleUnitMap = map[string]string{
%s}
`

const keyTemplate = `	"%s": "%s",
`

func main() {
	response, err := http.Get("https://mpsghub.actions.githubusercontent.com/_apis/connectionData?connectoptions=1")
	if err != nil {
		fmt.Printf("Failed to fetch data. Error: %v", err)
		return
	}
	defer response.Body.Close()

	if response.StatusCode != 200 {
		fmt.Printf("Failed to fetch data. status: %v", response.StatusCode)
		return
	}

	var data ConnectionData
	err = json.NewDecoder(response.Body).Decode(&data)
	if err != nil {
		fmt.Printf("Failed to decode data. Error: %v", err)
		return
	}

	validParentIdentifier := map[string]bool{
		PipelineScaleUnitType:      true,
		ArtifactCacheScaleUnitType: true,
		RunnerScaleUnitType:        true,
	}

	publicAccessMap := make(map[string]string)
	for _, serviceDefinition := range data.LocationServiceData.ServiceDefinitions {
		identifier := serviceDefinition.Identifier
		if serviceDefinition.ParentServiceType == "VsService" && validParentIdentifier[serviceDefinition.ParentIdentifier] {
			for _, accessMapping := range serviceDefinition.LocationMappings {
				if accessMapping.AccessMappingMoniker == "ScaleUnitMapping" {
					publicAccessMap[identifier] = strings.TrimSuffix(accessMapping.Location, "/")
				}
			}
		}
	}

	// Sort the keys of the publicAccessMap based on the values
	keys := make([]string, 0, len(publicAccessMap))
	values := make(map[string]string)
	for k, v := range publicAccessMap {
		keys = append(keys, k)
		values[k] = v
	}
	sort.Slice(keys, func(i, j int) bool {
		return values[keys[i]] < values[keys[j]]
	})

	// Save the publicAccessMap to a Go file
	file, err := os.Create("scale_unit_map.go")
	if err != nil {
		fmt.Printf("Failed to create file. Error: %v", err)
		return
	}
	defer file.Close()

	var sb strings.Builder
	for _, k := range keys {
		_, err = sb.WriteString(fmt.Sprintf(keyTemplate, k, publicAccessMap[k]))
		if err != nil {
			fmt.Printf("Failed to write to string builder. Error: %v", err)
			return
		}
	}

	_, err = file.WriteString(fmt.Sprintf(fileContent, sb.String()))
	if err != nil {
		fmt.Printf("Failed to write to file. Error: %v", err)
		return
	}
}
